parts.text:
[
  {
    "statement": "Cutting bracken in shrublands showed mixed outcomes.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Some studies found that cutting bracken led to increased heather cover or biomass and reduced bracken cover or biomass.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Other studies found no increase in heather cover or seedling abundance after cutting bracken.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Other studies found mixed or no reduction in bracken after cutting.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "One study found that cutting bracken increased species richness.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Another study found that cutting bracken did not alter species richness but did increase species diversity.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Cutting bracken increased the cover of wavy hair-grass and sheep’s fescue.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Cutting bracken did not increase gorse or common cow-wheat abundance.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "In one UK study, combining cutting with herbicide did not alter heather biomass.",
    "citations": [
      "1654"
    ]
  },
  {
    "statement": "In a Norway study, combining cutting with herbicide increased heather cover.",
    "citations": [
      "1654"
    ]
  },
  {
    "statement": "Combining cutting with herbicide had no significant effect on the cover of seven plant species in one UK study.",
    "citations": [
      "1654"
    ]
  },
  {
    "statement": "Plant species richness increased when cutting preceded herbicide application compared to the reverse order.",
    "citations": [
      "1654"
    ]
  },
  {
    "statement": "Combining cutting with herbicide reduced bracken biomass or cover in multiple studies.",
    "citations": [
      "1654"
    ]
  },
  {
    "statement": "Using herbicide with leaf-litter removal did not increase total plant biomass after eight years.",
    "citations": [
      "1660"
    ]
  },
  {
    "statement": "In three of six years, heather biomass was higher when using herbicide with leaf-litter removal than with herbicide alone.",
    "citations": [
      "1660"
    ]
  },
  {
    "statement": "No studies were found evaluating the effects of cutting and burning bracken.",
    "citations": [
      "1655"
    ]
  },
  {
    "statement": "No studies were found evaluating the use of herbicide with the sowing of shrubland seeds to control bracken.",
    "citations": [
      "1658"
    ]
  },
  {
    "statement": "A systematic review reported that repeated applications of the herbicide asulam reduced bracken abundance.",
    "citations": [
      "105"
    ]
  },
  {
    "statement": "A systematic review reported that cutting may be equally effective as repeated applications of the herbicide asulam for reducing bracken.",
    "citations": [
      "105"
    ]
  },
  {
    "statement": "A laboratory trial found the herbicide asulam inhibited the growth of three common moss species after three weeks of exposure.",
    "citations": [
      "105"
    ]
  },
  {
    "statement": "A laboratory trial found the herbicide asulam did not inhibit the growth of three common moss species after 24 hours of exposure.",
    "citations": [
      "105"
    ]
  }
]

[
  {
    "statement": "There is no available evidence on the success of legally protecting plant species affected by gathering in shrublands.",
    "citations": [
      "1612"
    ]
  },
  {
    "statement": "No studies evaluating the action of legally protecting plant species affected by gathering in shrublands were found.",
    "citations": [
      "1612"
    ]
  },
  {
    "statement": "No studies were found evaluating the effects on shrublands of legally protecting shrubland habitat.",
    "citations": [
      "1674",
      "1675"
    ]
  },
  {
    "statement": "No studies were found evaluating the effects on shrublands of legally protecting habitat around shrubland.",
    "citations": [
      "1674",
      "1675"
    ]
  }
]
